PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label ?rationale ?bfo ?incoming WHERE {
  VALUES ?s { <https://moosedev.dev/kg/Constraint/67d1a687-b03d-4a19-b372-b66c5338f53d> <https://moosedev.dev/kg/Constraint/2489ef27-a222-43cc-84d6-4ac9efe30585> }
  ?s rdfs:label ?label .
  OPTIONAL { ?s <https://moosedev.dev/kg/hasRationale> ?rationale }
  OPTIONAL { ?s <http://purl.obolibrary.org/obo/BFO_0000176> ?bfo }
  OPTIONAL { ?rationale2 <https://moosedev.dev/kg/isRationaleFor> ?s . BIND(?rationale2 AS ?incoming) }
}
ORDER BY ?label

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label ?rationale ?bfo ?incoming WHERE {
  VALUES ?s { <https://moosedev.dev/kg/Constraint/67d1a687-b03d-4a19-b372-b66c5338f53d> <https://moosedev.dev/kg/Constraint/2489ef27-a222-43cc-84d6-4ac9efe30585> }
  ?s rdfs:label ?label .
  OPTIONAL { ?s <https://moosedev.dev/kg/hasRationale> ?rationale }
  OPTIONAL { ?s <http://purl.obolibrary.org/obo/BFO_0000176> ?bfo }
  OPTIONAL { ?rationale2 <https://moosedev.dev/kg/isRationaleFor> ?s . BIND(?rationale2 AS ?incoming) }
}
ORDER BY ?label

SELECT DISTINCT ?c ?label ?rlabel WHERE {
  ?r a <https://trivyn.io/ontologies/software/architecture/domain/Rationale> ; <https://trivyn.io/ontologies/software/architecture/domain/isRationaleFor> ?c ; <https://trivyn.io/ontologies/software/architecture/domain/hasTitle> ?rlabel .
  ?c a <https://trivyn.io/ontologies/software/architecture/domain/Constraint> ; rdfs:label ?label .
}
ORDER BY LCASE(STR(?label))
LIMIT 10

SELECT DISTINCT ?c ?label ?rlabel WHERE {
  ?r a <https://trivyn.io/ontologies/software/architecture/domain/Rationale> ; <https://trivyn.io/ontologies/software/architecture/domain/isRationaleFor> ?c ; <https://trivyn.io/ontologies/software/architecture/domain/hasTitle> ?rlabel .
  ?c a <https://trivyn.io/ontologies/software/architecture/domain/Constraint> ; rdfs:label ?label .
}
ORDER BY LCASE(STR(?label))
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (GROUP_CONCAT(CONCAT(STR(?label), " | ", STR(?s)); separator="\n") AS ?list) WHERE {
  { SELECT ?s ?label WHERE {
      ?s a <https://trivyn.io/ontologies/software/architecture/domain/Constraint> ; rdfs:label ?label .
    } ORDER BY LCASE(STR(?label))
  }
}

